fn solve(a: i8, b: i8, s: Vec<char>) -> Vec<char> {
    // Convert a and b to usize for indexing and length checks
    let a = a as usize;
    let b = b as usize;

    // The string length must be exactly a + b + 1
    if s.len() != a + b + 1 {
        return vec!['N', 'o'];
    }

    // We'll count hyphens and ensure it's in the correct place,
    // and also verify all other characters are digits.
    let mut hyphen_count = 0;
    for (i, &c) in s.iter().enumerate() {
        if c == '-' {
            hyphen_count += 1;
            // Hyphen must appear exactly at index `a`.
            if i != a {
                return vec!['N', 'o'];
            }
        } else if !c.is_ascii_digit() {
            // Any non-digit (other than the one hyphen) is invalid
            return vec!['N', 'o'];
        }
    }

    // Finally, there must be exactly one hyphen
    if hyphen_count == 1 {
        vec!['Y', 'e', 's']
    } else {
        vec!['N', 'o']
    }
}

